html:
{% if doc.docstatus == 1 %}
{% set patient = frappe.get_doc('Patient', doc.patient) %}
{% set p_age, age_type = frappe.db.get_value(
    "Patient", doc.patient, ["p_age", "age_type"]
) %}
{% set served_by = frappe.db.get_value("User", doc.owner, "full_name") %}

<div class="wrapper">
  <div class="invoice_wrapper">

    <!-- LETTER HEAD -->
    <div class="header">
      {% if letter_head and not no_letterhead -%}
        <!--<div class="letter-head">{{ letter_head }}</div>-->
            <div class="letter-head text-center">
        <img  src="/files/Screenshot from 2026-01-14 09-14-53.png"/>
    </div>
      {% endif %}
    </div>

    <!-- META -->
    <div class="meta">
      <p class="bold">Patient: {{ patient.name }}</p>
      <p class="bold">Patient Name: {{ patient.patient_name }}</p>

      <p class="bold">
        {{ _("Age: ") }}
        {{ p_age }} {{ age_type }}
      </p>

      <p class="bold">{{ _("Doctor: ") }} {{ doc.ref_practitioner or '' }}</p>

      <p class="bold">
        {{ _("Invoice Date: ") }} {{ doc.get_formatted("posting_date") }},
        {{ doc.get_formatted("posting_time") }}
      </p>

      <!--<p class="bold">-->
      <!--  {{ _("Served By: ") }} {{ frappe.db.get_value("User", doc.owner, "full_name") }}-->
      <!--</p>-->
    </div>

    <!-- ITEMS -->
    <div class="body">
      <div class="main_table">
        <div class="table_header">
          <div class="myrow">
            <div class="col col_no">NO.</div>
            <div class="col col_des">DESCRIPTION</div>
            <div class="col col_qty">QTY</div>
          </div>
        </div>

        <div class="table_body">
          {% for item in doc.items %}
          <div class="myrow">
            <div class="col col_no">
              <p>{{ item.idx }}</p>
            </div>

            <div class="col col_des">
              <p>{{ item.item_name or item.item_code }}</p>
            </div>

            <div class="col col_qty">
              <p>{{ (item.qty or 0) | round(0) | int }}</p>
            </div>
          </div>
          {% endfor %}
        </div>
      </div>

      <!-- TOTALS
           CHANGED: totals now use 2 fixed columns: label + amount.
           This keeps "Net / Paid / Rest" close to the amount and aligned.
      -->
      <div class="totals_wrap">
        <div class="totals_table">

          <div class="trow">
            <div class="tlabel">Total</div>
            <div class="tamt">${{ doc.total }}</div>
          </div>

          {% if doc.total_taxes_and_charges %}
          <div class="trow">
            <div class="tlabel bold">Vat (Tax 5%)</div>
            <div class="tamt">${{ doc.total_taxes_and_charges }}</div>
          </div>
          {% endif %}

          {% if doc.discount_amount %}
          <div class="trow">
            <div class="tlabel">Discount</div>
            <div class="tamt">${{ doc.discount_amount }}</div>
          </div>
          {% endif %}

          <div class="trow">
            <div class="tlabel bold">Net</div>
            <div class="tamt bold">${{ doc.grand_total }}</div>
          </div>

          <div class="trow">
            <div class="tlabel bold">Paid</div>
            <div class="tamt">${{ doc.paid_amount }}</div>
          </div>

          <div class="trow">
            <div class="tlabel bold">Rest</div>
            <div class="tamt">${{ doc.outstanding_amount }}</div>
          </div>

        </div>
      </div>

      <!-- CUT AREA (visual only)
           NOTE: real auto-cut depends on printer ESC/POS/driver, not CSS.
      -->
      <div class="cut-area">
        <div class="cut-line">--------------------------------</div>
        <div class="cut-text">
        <p class="bold">
            {{ _("Served By: ") }} {{ served_by }}
        </p>
        </div>
      </div>

    </div>
  </div>
</div>

{% endif %}

<style>
/*@import url('https://fonts.googleapis.com/css2?family=Lato:wght@100;400;900&display=swap');*/

/* =========================================================
   ADJUST PRINT SIZE HERE (MOST IMPORTANT SETTINGS)
   =========================================================

   1) For thermal printers:
      - 80mm paper: use RECEIPT_WIDTH = 80mm
      - 58mm paper: use RECEIPT_WIDTH = 58mm

   2) For A4/A5 printing:
      - Set PRINT_MODE to "A4" or "A5"
      - The @page rule will switch to A4/A5 automatically

   How to know if your printer is 58mm or 80mm?
   - Check the paper roll width you buy (it will say 57/58mm or 80mm)
   - Or check printer model specs (most common are 58mm or 80mm)
   - Or measure the roll with a ruler

   Quick tip:
   58mm paper normally prints fewer characters per line than 80mm.
*/

/* CHANGE THIS IF NEEDED */
:root{
  --PRINT_MODE: receipt;   /* options: receipt, A4, A5 */
  --RECEIPT_WIDTH: 80mm;   /* change to 58mm if your roll is 58mm */
  --secondary: #3d3d3d;
}

/* remove browser default margins (fix left gap) */
html, body { margin: 0 !important; padding: 0 !important; }

*{
  box-sizing: border-box;
  font-family: Arial, Helvetica, sans-serif !important;
  font-size: 12px;
  color: #000;
}
.bold{ font-weight: 900; }

/* Outer wrapper */
.wrapper{
  background: #fff;
  margin: 0 !important;
  padding: 0 !important;
}

/* Receipt container */
.invoice_wrapper{
  width: var(--RECEIPT_WIDTH);
  max-width: var(--RECEIPT_WIDTH);
  margin: 0 !important;      /* no centering */
  padding: 0 !important;
}

/* Small safe padding (so it doesn't touch edges)
   If you want tighter left/right: change 2mm -> 0mm
*/
.meta, .body{ padding: 0 2mm; }

.meta{ margin-top: 2mm; margin-bottom: 2mm; }
.meta p{ margin: 0 0 2px 0; }

/* ITEMS TABLE */
.main_table{
  margin-top: 6px;
  border-top: 1px solid #000;
}
.myrow{
  display: flex;
  border-bottom: 1px solid var(--secondary);
}
.myrow .col{
  padding: 2px 0;
}
.col_no  { width: 10%; }
.col_des { width: 70%; padding-left: 2mm; } /* adjust indent here */
.col_qty { width: 20%; text-align: right; }

/* TOTALS (label + amount close together) */
.totals_wrap{
  margin-top: 6px;
  display: flex;
  justify-content: flex-end;
}
.totals_table{
  width: 100%;
  max-width: 60mm; /* <-- ADJUST THIS to bring totals closer.
                      Smaller = totals block becomes narrower and moves right.
                      Try: 55mm or 50mm for tighter look on 80mm paper. */
}
.trow{
  display: flex;
  border-bottom: 1px solid #000;
  padding: 2px 0;
}
.trow:last-child{ border-bottom: none; }

/* label column (left) */
.tlabel{
  width: 55%;       /* <-- adjust label width */
  text-align: left;
  padding-right: 6px;
}

/* amount column (right) */
.tamt{
  width: 45%;       /* <-- adjust amount width */
  text-align: right;
  white-space: nowrap;
}

/* CUT AREA */
.cut-area{
  margin-top: 10px;
  padding-top: 6px;
  text-align: center;
}
.cut-line{ font-size: 12px; }
.cut-text{ font-size: 10px; margin-top: 2px; }

/* =========================================================
   PRINT RULES
   ========================================================= */
@media print {

  /* RECEIPT MODE (thermal) */
  @page{
    /* Default: receipt width */
    size: var(--RECEIPT_WIDTH) auto;
    margin: 0 !important;
  }

  html, body{
    width: var(--RECEIPT_WIDTH) !important; /* prevents centering */
    margin: 0 !important;
    padding: 0 !important;
  }

  .wrapper, .invoice_wrapper{
    margin: 0 !important;
    padding: 0 !important;
  }

  /* extra blank space helps the cutter/driver cut after content */
  .cut-area{ padding-bottom: 20mm; }
}

/* =========================================================
   OPTIONAL: A4 / A5 OVERRIDES
   If you want to print this format on A4/A5, you can:
   - Create another Print Format named "POS Receipt A4"
     and change RECEIPT_WIDTH + @page to A4 here.
   - OR copy this code and change @page size to A4/A5.
   ========================================================= */

/*
@media print {
  @page { size: A4; margin: 10mm; }
  .invoice_wrapper { width: 100% !important; max-width: 100% !important; }
  html, body { width: auto !important; }
  .meta, .body { padding: 0 !important; }
  .totals_table { max-width: 90mm; }
}
*/

/*
@media print {
  @page { size: A5; margin: 10mm; }
  .invoice_wrapper { width: 100% !important; max-width: 100% !important; }
  html, body { width: auto !important; }
  .meta, .body { padding: 0 !important; }
  .totals_table { max-width: 80mm; }
}
*/
</style>

{% set printed_departments = [] %}

{% if doc.lab_test %}
  {% for samp in doc.lab_test %}
    {% set dept = (samp.lab_department or '').strip() %}
    {% if dept and dept.upper() not in printed_departments %}
      {% set _ = printed_departments.append(dept.upper()) %}

      <div class="label-page">
        <div class="label">

          <!-- ONE CENTER COLUMN (everything aligns to this width) -->
          <div class="center-col">

            <div class="top">
              <div class="pname">{{ doc.patient_name or '' }}</div>
              <div class="pid">{{ doc.patient or '' }} / Lab-{{ doc.lab_ref or '' }}</div>
            </div>

            <div class="mid">
              <img class="barcode" src="/files/barcode.png" alt="barcode" />
            </div>

            <div class="bottom">
              <div class="dept">{{ dept }} / NO: {{ doc.token_no }}</div>
              <!--<div class="dept">Time: -->
              <!--{{ doc.collected_time }}-->
              <!--{{ frappe.utils.formatdate(doc.collected_time) }}-->
              <!--{{(doc.collected_time | string).split(' ')[0]}}-->
              <!--</div>-->
              <div class="dept">Date: {{ frappe.utils.formatdate(doc.collected_time) }}</div>
<div class="dept">Time: {{ frappe.utils.get_datetime(doc.collected_time).strftime('%I:%M %p') }}</div>
            </div>

          </div>

        </div>
      </div>

    {% endif %}
  {% endfor %}
{% endif %}

<style>
/* ===========================
   MAIN SETTINGS (CHANGE HERE)
   =========================== */
:root{
  --PAGE_W: 4in;       /* 4-inch roll printer width */
  --PAGE_H: 2in;       /* label height (adjust if needed) */

  --PAD_X: 2mm;
  --PAD_Y: 2mm;

  /* Barcode size (this defines the center column width) */
  --BAR_W: 84mm;
  /*--BAR_W: 64mm;*/
  /*--BAR_H: 22mm;*/
  --BAR_H: 15mm;

  /* ⭐ If barcode looks slightly left/right due to PNG padding,
     adjust this. Positive = move right, Negative = move left.
     Start with: 0mm then try 0.5mm, 1mm, -0.5mm */
  --BAR_SHIFT_X: 0mm;

  --FONT_MAIN: 12pt;
  --FONT_SMALL: 8.5pt;
}

html, body { margin:0 !important; padding:0 !important; }

@media print{
  @page{
    size: var(--PAGE_W) var(--PAGE_H);
    margin: 0 !important;
  }
  .label-page{ page-break-after: always; break-after: page; }
  .label-page:last-child{ page-break-after: auto; break-after: auto; }
}

/* page */
.label-page{
  width: var(--PAGE_W);
  height: var(--PAGE_H);
  display: flex;
  align-items: center;
  /*justify-content: center;*/
   justify-content: flex-start;
}

/* label */
.label{
  width: calc(var(--PAGE_W) - (var(--PAD_X) * 2));
  height: calc(var(--PAGE_H) - (var(--PAD_Y) * 2));
  padding: var(--PAD_Y) var(--PAD_X);
  box-sizing: border-box;

  display: flex;
  align-items: center;
  /*justify-content: center;*/
    justify-content: flex-start;
}

/* ✅ the magic: one fixed center column */
.center-col{
  width: var(--BAR_W);           /* everything aligns to barcode width */
  display: flex;
  flex-direction: column;
  align-items: center;
  /*justify-content: center;*/
  justify-content: flex-start;
  
  gap: 2mm;
}

/* text blocks match same column width */
.top, .bottom{
  width: 100%;
  text-align: center;
  line-height: 1.05;
}

.pname{
  font-size: var(--FONT_MAIN);
  font-weight: 800;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  /*text-wrap: wrap;*/
  text-align: left;
  
}
.pid, .dept{
  font-size: var(--FONT_MAIN);
  font-weight: 800;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: left;
}

/* barcode */
.mid{
  width: 100%;
  display: flex;
  justify-content: left;
  /*justify-content: left;*/
  align-items: left;
  /*align-items: flex-start;*/
}

.barcode{
  width: var(--BAR_W);
  height: var(--BAR_H);
  /*object-fit: contain;*/
  /*display: block;*/

  /* ✅ micro-adjust if PNG has uneven internal whitespace */
  /*transform: translateX(var(--BAR_SHIFT_X));*/

  /* crispness */
  image-rendering: crisp-edges;
  image-rendering: pixelated;
  /*text-align: left;*/
  
  /* display: flex;*/
  /*justify-content: left;*/
}
</style>

