*{
    font-size: 11px;
}

  /* ===== GLOBAL SETTINGS ===== */
  @page {
    size: A4;
    margin: 5mm; /* Narrow margins for single page */
  }

  html, body { margin: 0; padding: 0; }
  *, *::before, *::after { box-sizing: border-box; }

  .wrap {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 11px; /* Smaller font for better fit */
    color: #111;
    width: 100%;
    line-height: 1.3;
  }

  .page {
    width: 100%;
    max-width: 200mm;
    margin: 0 auto;
