  /* ===== HEADER & LOGO ===== */
  .letter-head img {
    max-width: 100%;
    height: auto;
    max-height: 30mm; /* Limit logo height */
  }

  .title {
    text-align: center;
    font-weight: 800;
    font-size: 15px;
    margin: 5px 0;
    text-decoration: underline;
  }

  /* ===== INFO CARD ===== */
  .info-card {
