html:
{# ==============================
   EMPLOYEE ADVANCE (CLEAN + 3 SIGNATURES)
   - Uses Letterhead ({{ letter_head }})
   - Pulls Employee details from Employee doctype (not doc.employee_name)
   - Hides internal fields (Advance Account, Currency)
   - Shows: Employee + Posting Date + Status + Purpose + Amounts
   - Signatures: Prepared By / Approved By / Received By
================================ #}

{% set emp = frappe.get_doc("Employee", doc.employee) %}
{% set emp_name = emp.employee_name or doc.employee %}
{% set emp_dept = emp.department or "" %}
{% set emp_desig = emp.designation or "" %}

{# Prepared / Approved users (creator + submitter/modifier on submit) #}
{% set prepared_by_user = doc.owner %}
{% set prepared_by = frappe.db.get_value("User", prepared_by_user, "full_name") or prepared_by_user %}

{# If you later implement workflow, create a custom field: doc.approved_by (Link User)
   and replace approved_by_user = doc.approved_by
#}
{% set approved_by_user = doc.modified_by if doc.docstatus == 1 else "" %}
{% set approved_by = (frappe.db.get_value("User", approved_by_user, "full_name") or approved_by_user) if approved_by_user else "" %}

<style>
    .ea-wrap{
        font-family: "Segoe UI", Tahoma, Arial, sans-serif;
        font-size: 12.5px;
        color: #1f2d3d;
    }

    .ea-title{
        text-align:center;
        margin: 8px 0 12px 0;
    }
    .ea-title h2{
        margin:0;
        font-size: 20px;
        letter-spacing: .8px;
        text-transform: uppercase;
    }
    .ea-title .ref{
        margin-top: 4px;
        color:#6c757d;
        font-size: 11px;
    }

    .ea-divider{
        border: 0;
        border-top: 1px solid #212529;
        margin: 10px 0 14px 0;
        opacity: .8;
    }

    .ea-grid{
        width:100%;
        border-collapse: collapse;
        table-layout: fixed;
    }
    .ea-grid td{
        padding: 6px 8px;
        vertical-align: top;
    }
    .ea-field-label{
        font-weight: 800;
        color:#212529;
        width: 22%;
        white-space: nowrap;
    }
    .ea-field-value{
        width: 28%;
    }

    .ea-card{
        margin-top: 14px;
        border: 1px solid #e9ecef;
        border-radius: 8px;
        padding: 12px 14px;
        background: #fbfcfd;
    }

    .ea-section-title{
        font-weight: 900;
        margin-bottom: 6px;
        color:#212529;
        font-size: 12px;
    }

    .ea-purpose{
        white-space: pre-wrap;
        min-height: 52px;
        line-height: 1.5;
    }

    .ea-amounts{
        width:100%;
        border-collapse: collapse;
        margin-top: 4px;
    }
    .ea-amounts td{
        padding: 6px 2px;
    }
    .ea-amounts .k{
        font-weight: 800;
        color:#212529;
        width: 60%;
    }
    .ea-amounts .v{
        text-align: right;
        font-variant-numeric: tabular-nums;
        width: 40%;
        font-weight: 800;
    }

    /* 3 signatures */
    .ea-sign-row{
        margin-top: 42px;
        display:flex;
        justify-content: space-between;
        gap: 18px;
    }
    .ea-sign-box{
        width: 32%;
        text-align:center;
    }
    .ea-sign-line{
        margin-top: 54px;
        border-top: 2px dashed #2f343a;
        padding-top: 6px;
        font-weight: 900;
        font-size: 12px;
    }
    .ea-sign-meta{
        margin-top: 4px;
        font-size: 11px;
        color:#212529;
        font-weight: 700;
        min-height: 14px;
    }
    .ea-sign-note{
        margin-top: 2px;
        color:#6c757d;
        font-size: 11px;
        font-weight: 600;
    }

    .ea-footer{
        margin-top: 22px;
        border-top: 1px solid #e9ecef;
        padding-top: 8px;
        text-align:center;
        font-size: 10.5px;
        color:#6c757d;
    }

    @media print{
        .ea-wrap{ margin: 0; }
    }
</style>

<div class="ea-wrap">
    {{ letter_head }}

    <div class="ea-title">
        <h2>Employee Advance</h2>
        <div class="ref">Reference No: {{ doc.name }}</div>
    </div>

    <hr class="ea-divider">

    <!-- Main Info (CLEAN) -->
    <table class="ea-grid">
        <tr>
            <td class="ea-field-label">Employee</td>
            <td class="ea-field-value">{{ doc.employee }}</td>

            <td class="ea-field-label">Posting Date</td>
            <td class="ea-field-value">{{ doc.posting_date }}</td>
        </tr>

        <tr>
            <td class="ea-field-label">Employee Name</td>
            <td class="ea-field-value">{{ emp_name }}</td>

            <td class="ea-field-label">Status</td>
            <td class="ea-field-value">{{ doc.status }}</td>
        </tr>

        <tr>
            <td class="ea-field-label">Department</td>
            <td class="ea-field-value">{{ emp_dept or "-" }}</td>

            <td class="ea-field-label">Designation</td>
            <td class="ea-field-value">{{ emp_desig or "-" }}</td>
        </tr>
    </table>

    <!-- Purpose -->
    <div class="ea-card">
        <div class="ea-section-title">Purpose of Advance</div>
        <div class="ea-purpose">{{ doc.purpose or "-" }}</div>
    </div>

    <!-- Amounts -->
    <div class="ea-card">
        <div class="ea-section-title">Amounts</div>
        <table class="ea-amounts">
            <tr>
                <td class="k">Advance Amount</td>
                <td class="v">{{ frappe.utils.fmt_money(doc.advance_amount, currency=doc.currency) }}</td>
            </tr>

            {# Show Paid Amount only if it exists/meaningful #}
            {% if (doc.paid_amount or 0) %}
            <tr>
                <td class="k">Paid Amount</td>
                <td class="v">{{ frappe.utils.fmt_money(doc.paid_amount, currency=doc.currency) }}</td>
            </tr>
            {% endif %}

            {# Optional fields (uncomment if you want) #}
            {#
            {% if doc.claimed_amount %}
            <tr>
                <td class="k">Claimed Amount</td>
                <td class="v">{{ frappe.utils.fmt_money(doc.claimed_amount, currency=doc.currency) }}</td>
            </tr>
            {% endif %}

            {% if doc.return_amount %}
            <tr>
                <td class="k">Returned Amount</td>
                <td class="v">{{ frappe.utils.fmt_money(doc.return_amount, currency=doc.currency) }}</td>
            </tr>
            {% endif %}
            #}
        </table>
    </div>

    <!-- Signatures: Prepared / Approved / Received -->
    <div class="ea-sign-row">
        <div class="ea-sign-box">
            <div class="ea-sign-line">Prepared By</div>
            <div class="ea-sign-meta">{{ prepared_by or "-" }}</div>
            <div class="ea-sign-note">HR / Accountant Signature</div>
        </div>

        <div class="ea-sign-box">
            <div class="ea-sign-line">Approved By</div>
            <div class="ea-sign-meta">{{ approved_by or "-" }}</div>
            <div class="ea-sign-note">Manager Signature & Stamp</div>
        </div>

        <div class="ea-sign-box">
            <div class="ea-sign-line">Received By</div>
            <div class="ea-sign-meta">{{ emp_name }}</div>
            <div class="ea-sign-note">Employee Signature</div>
        </div>
    </div>

    <div class="ea-footer">
        This document is system generated. Signature is required for payment release and audit compliance.
    </div>
</div>

{# ==============================
   PAYMENT / RECEIPT VOUCHER (SIMPLE)
   - Works for Customer / Supplier / Employee
   - Works for Pay / Receive
   - No accounts
   - No allocations
   - No balances
   - Shows: Party + Amount + Remarks + Reference + Signatures
================================ #}

{% set party_name = doc.party_name or doc.party %}
{% set currency = doc.paid_from_account_currency or doc.paid_to_account_currency or doc.company_currency or doc.currency %}

{% set paid_amt = doc.paid_amount or 0 %}
{% set recv_amt = doc.received_amount or 0 %}

{# Determine voucher type + amount #}
{% if (doc.payment_type or "").lower() == "pay" %}
  {% set voucher_title = "Payment Voucher" %}
  {% set main_label = "Payment Amount" %}
  {% set main_amt = paid_amt %}
{% elif (doc.payment_type or "").lower() == "receive" %}
  {% set voucher_title = "Receipt Voucher" %}
  {% set main_label = "Receipt Amount" %}
  {% set main_amt = recv_amt if recv_amt else paid_amt %}
{% else %}
  {% set voucher_title = "Payment Voucher" %}
  {% set main_label = "Amount" %}
  {% set main_amt = paid_amt if paid_amt else recv_amt %}
{% endif %}

{# Prepared / Approved names (simple + safe) #}
{% set prepared_by_user = doc.owner %}
{% set prepared_by = frappe.db.get_value("User", prepared_by_user, "full_name") or prepared_by_user %}

{# If you later add workflow, replace this with doc.approved_by custom field #}
{% set approved_by_user = doc.modified_by if doc.docstatus == 1 else "" %}
{% set approved_by = (frappe.db.get_value("User", approved_by_user, "full_name") or approved_by_user) if approved_by_user else "" %}

<style>
